def _dedupe_keep_first(seq: Iterable) -> list:
    """Many class files re-export classic cards. Keep first occurrence."""
    seen: set[int] = set()
    out: list = []
    for c in seq:
        if c is None:
            continue
        if id(c) in seen:
            continue
        seen.add(id(c))
        out.append(c)
    return out


ALL_CARDS_BY_FILE: list[tuple[str, list]] = [
    (label, _dedupe_keep_first(cards)) for label, cards in CARD_GROUPS
]

# Flatten with first-seen-file label so each card gets tested exactly once.
_FIRST_SEEN_LABEL: dict[int, str] = {}
ALL_UNIQUE_CARDS: list = []
for label, cards in ALL_CARDS_BY_FILE:
    for c in cards:
        if c is None:
            continue
        if id(c) in _FIRST_SEEN_LABEL:
            continue
        _FIRST_SEEN_LABEL[id(c)] = label
        ALL_UNIQUE_CARDS.append(c)


