def _new_scene(p1_class: str = "Mage", p2_class: str = "Warrior") -> tuple[Game, Any, Any]:
    """Build a 2-player Hearthstone game with full hero+hero-power setup.

    Also pre-configures:
      - p1.cards_played_this_turn = 1 (Combo cards active)
      - p1.armor = 5 (Shield Slam / Shield Block payoff)
    """
    game = Game(mode="hearthstone")
    p1 = game.add_player("P1", life=30)
    p2 = game.add_player("P2", life=30)
    game.setup_hearthstone_player(p1, HEROES[p1_class], HERO_POWERS[p1_class])
    game.setup_hearthstone_player(p2, HEROES[p2_class], HERO_POWERS[p2_class])
    # Combo enablement — SI:7 Agent / Defias Ringleader / Eviscerate / Edwin
    # all read player.cards_played_this_turn > 0.
    p1.cards_played_this_turn = 1
    p2.cards_played_this_turn = 1
    # Armor enablement — Shield Slam deals damage equal to your armor.
    p1.armor = 5
    return game, p1, p2


def _populate_libraries(game: Game, p1: Any, p2: Any, n: int = 10) -> None:
    """Stock both libraries so DRAW events don't no-op via fatigue."""
    filler = next((c for c in BASIC_CARDS if c.name == "Wisp"), None)
    if filler is None:
        return
    for _ in range(n):
        game.add_card_to_library(p1.id, filler)
        game.add_card_to_library(p2.id, filler)


def _populate_hands(game: Game, p1: Any, p2: Any, n: int = 3) -> None:
    """Drop a few cards into each hand so 'gain X for each card in hand'
    triggers (Twilight Drake, Ancient Watcher post-Edwin, etc.) have a
    non-zero hand to count."""
    filler = next((c for c in BASIC_CARDS if c.name == "Wisp"), None)
    if filler is None:
        return
    for owner in (p1, p2):
        for _ in range(n):
            game.create_object(
                name=filler.name,
                owner_id=owner.id,
                zone=ZoneType.HAND,
                characteristics=filler.characteristics,
                card_def=filler,
            )


def _place_minion(game: Game, card_def: Any, owner: Any,
                  zone: ZoneType = ZoneType.BATTLEFIELD) -> GameObject:
    """Create an object from a card_def in the requested zone."""
    return game.create_object(
        name=card_def.name,
        owner_id=owner.id,
        zone=zone,
        characteristics=card_def.characteristics,
        card_def=card_def,
    )


def _populate_friendly_board(game: Game, owner: Any) -> list[GameObject]:
    """Drop a varied friendly board so target-choice / buff cards have legal picks.

    Includes: vanilla Wisp, 4/5 Yeti, a Murloc (for tribal triggers),
    a damaged Beast (Houndmaster / Bestial Wrath), and a Divine-Shield
    Yeti (Blood Knight / Argent Protector). Also equips a Light's Justice
    so weapon-buff cards (Captain Greenskin, Deadly Poison, Bite) have
    a real weapon to buff.
    """
    bf: list[GameObject] = []
    wisp = next((c for c in BASIC_CARDS if c.name == "Wisp"), None)
    yeti = next((c for c in BASIC_CARDS if c.name == "Chillwind Yeti"), None)
    murloc = next((c for c in BASIC_CARDS if c.name == "Murloc Raider"), None)
    raptor = next((c for c in BASIC_CARDS if c.name == "Bloodfen Raptor"), None)
    if wisp:
        bf.append(_place_minion(game, wisp, owner))
    if yeti:
        ds_yeti = _place_minion(game, yeti, owner)
        ds_yeti.state.divine_shield = True
        bf.append(ds_yeti)
    if murloc:
        bf.append(_place_minion(game, murloc, owner))
    if raptor:
        # Mark as damaged so Houndmaster/Power Word: Shield-style buff
        # cards have a "wounded beast" target. Bestial Wrath / Mark of
        # the Wild target by subtype, not damage, so this is fine either way.
        wounded_beast = _place_minion(game, raptor, owner)
        wounded_beast.state.damage = 1
        bf.append(wounded_beast)
    # Demon — for Sacrificial Pact / Void Terror / Soulfire chain.
    from src.cards.hearthstone.tokens import IMP
    if IMP:
        bf.append(_place_minion(game, IMP, owner))
    # Give the caster a weapon (Captain Greenskin / Deadly Poison /
    # Savagery / Bite — all check player.weapon_attack > 0).
    owner.weapon_attack = 2
    owner.weapon_durability = 3
    return bf


def _populate_enemy_board(game: Game, enemy: Any) -> list[GameObject]:
    """Drop a maximal enemy board so conditional triggers can fire.

    Targets common conditional cards:
      - 4+ enemy minions (Mind Control Tech)
      - a 7+ ATK enemy minion (Big Game Hunter, Death Bite)
      - a Taunt-keyworded enemy (Black Knight)
      - damaged enemies (Execute, Backstab)
      - enemy with a weapon equipped (Acidic Swamp Ooze, Harrison Jones)
    """
    bf: list[GameObject] = []
    ogre = next((c for c in BASIC_CARDS if c.name == "Boulderfist Ogre"), None)
    wisp = next((c for c in BASIC_CARDS if c.name == "Wisp"), None)
    boar = next((c for c in BASIC_CARDS if c.name == "Stonetusk Boar"), None)
    sen_jin = next((c for c in BASIC_CARDS if c.name == "Sen'jin Shieldmasta"), None)
    core_hound = next((c for c in BASIC_CARDS if c.name == "Core Hound"), None)
    if ogre:
        big = _place_minion(game, ogre, enemy)
        # Mark as damaged so Execute / Backstab-style cards have a legal pick.
        big.state.damage = 1
        bf.append(big)
    if core_hound:
        # 9 ATK — feeds Big Game Hunter / Death's Bite / Hunter's Mark.
        bf.append(_place_minion(game, core_hound, enemy))
    if wisp:
        bf.append(_place_minion(game, wisp, enemy))
    if boar:
        bf.append(_place_minion(game, boar, enemy))
    if sen_jin:
        # Taunt minion — for Black Knight, Eaglehorn Bow, etc.
        bf.append(_place_minion(game, sen_jin, enemy))

    # Equip a fake weapon on the enemy so weapon-destruction cards have
    # something to destroy. Skip the full make_weapon ETB plumbing —
    # battlecries that "destroy enemy weapon" check player.weapon_*.
    enemy.weapon_attack = 3
    enemy.weapon_durability = 2
    return bf


