def _classify(card: Any) -> str:
    """Classify the card by which trigger we should fire."""
    if not hasattr(card, "characteristics"):
        return "skip:bad-card"
    if getattr(card, "battlecry", None):
        return "battlecry"
    if getattr(card, "deathrattle", None):
        return "deathrattle"
    if getattr(card, "spell_effect", None):
        return "spell"
    types = card.characteristics.types or set()
    if CardType.HERO in types:
        return "hero"
    if CardType.HERO_POWER in types:
        return "hero_power"
    if getattr(card, "setup_interceptors", None):
        # Pure setup_interceptors with no battlecry/deathrattle —
        # passives (Raid Leader, Spell Damage +1), enrage triggers,
        # cost-reduction auras, etc.
        return "passive"
    if CardType.WEAPON in types:
        return "weapon"
    if CardType.MINION in types:
        return "vanilla_minion"
    return "skip:other"


_KEYWORD_TEXT_ALIASES: set[str] = {
    "", "taunt", "charge", "divine shield", "stealth", "windfury",
    "rush", "lifesteal", "poisonous",
    # Common combos baked into vanilla minions via the `keywords=` param.
    "charge, divine shield", "divine shield, charge",
    "taunt, divine shield", "divine shield, taunt",
    "charge, windfury", "windfury, charge",
    "taunt, charge", "charge, taunt",
    # Mech / dragon / murloc tribal markers in basic flavour text.
    "elusive — cannot be targeted by spells or hero powers.",
}


def _is_vanilla(card: Any) -> bool:
    """Vanilla minion = no triggers, no text effect (just stats + maybe keyword).

    Cards whose only ability is a baked-in keyword (Argent Squire's
    Divine Shield, Stonetusk Boar's Charge) flow through `make_minion`'s
    ``keywords=`` path: there's no setup function, the state is set
    directly in the factory. From a 'does this card work?' standpoint
    these behave like vanillas and pass.
    """
    text = (getattr(card, "text", "") or "").strip().lower()
    has_real_effect = (
        getattr(card, "battlecry", None)
        or getattr(card, "deathrattle", None)
        or getattr(card, "spell_effect", None)
    )
    if has_real_effect:
        return False
    # setup_interceptors may have been auto-attached by make_minion just to
    # carry a keyword bake-in. Detect by inspecting characteristics.abilities.
    if getattr(card, "setup_interceptors", None):
        # If the only abilities are keyword markers and the text is keyword
        # boilerplate, treat as vanilla. Lord/aura cards will have text like
        # "your other minions have +1 attack" — those won't match.
        if text in _KEYWORD_TEXT_ALIASES:
            return True
        return False
    return text in _KEYWORD_TEXT_ALIASES


# =============================================================================
# Per-classification firing
# =============================================================================


def _zone_size(state: GameState, key: str) -> int:
    z = state.zones.get(key)
    return len(z.objects) if z else 0


def _minion_state_fingerprint(state: GameState) -> tuple:
    """Hash all minion object state slots cards may directly mutate.

    Captures summoning_sickness, frozen, divine_shield, stealth, taunt,
    windfury, total ability count, current damage, base power/toughness.
    Cards like Charge spell, Inner Fire, Mark of the Wild mutate these
    directly without emitting events.
    """
    bf = state.zones.get("battlefield")
    if not bf:
        return ()
    fp: list = []
    for mid in bf.objects:
        obj = state.objects.get(mid)
        if not obj:
            continue
        st = obj.state
        chars = obj.characteristics
        fp.append((
            mid,
            getattr(st, "summoning_sickness", False),
            getattr(st, "frozen", False),
            getattr(st, "divine_shield", False),
            getattr(st, "stealth", False),
            getattr(st, "windfury", False),
            getattr(st, "damage", 0),
            chars.power,
            chars.toughness,
            len(chars.abilities or []),
            len(chars.subtypes or set()),
        ))
    return tuple(fp)


def _snapshot_state(state: GameState) -> dict:
    """Capture state slots that 'silent' cards mutate directly.

    Includes player stats AND per-zone object counts so cards that draw,
    discard, mill, or summon directly (without emitting events) still
    register as 'doing something'. Also captures a fingerprint of every
    minion on the battlefield so cards that mutate object state (Charge
    spell granting 'charge', Inner Fire setting power=toughness, etc.)
    can be detected.
    """
    snap: dict[str, Any] = {}
    snap["interceptor_count"] = len(state.interceptors)
    snap["pending_choice"] = state.pending_choice is not None
    snap["battlefield_count"] = _zone_size(state, "battlefield")
    snap["minion_fp"] = _minion_state_fingerprint(state)
    snap["players"] = {}
    snap["zones"] = {}
    for pid, p in state.players.items():
        snap["players"][pid] = (
            getattr(p, "mana_crystals", 0),
            getattr(p, "mana_crystals_available", 0),
            getattr(p, "armor", 0),
            getattr(p, "weapon_attack", 0),
            getattr(p, "weapon_durability", 0),
            getattr(p, "life", 30),
            getattr(p, "fatigue_damage", 0),
        )
        snap["zones"][pid] = (
            _zone_size(state, f"hand_{pid}"),
            _zone_size(state, f"library_{pid}"),
            _zone_size(state, f"graveyard_{pid}"),
        )
    return snap


def _state_mutated(before: dict, state: GameState) -> bool:
    """Return True if any tracked state slot changed."""
    if len(state.interceptors) != before["interceptor_count"]:
        return True
    if (state.pending_choice is not None) != before["pending_choice"]:
        return True
    if _zone_size(state, "battlefield") != before["battlefield_count"]:
        return True
    if _minion_state_fingerprint(state) != before["minion_fp"]:
        return True
    for pid, p in state.players.items():
        cur = (
            getattr(p, "mana_crystals", 0),
            getattr(p, "mana_crystals_available", 0),
            getattr(p, "armor", 0),
            getattr(p, "weapon_attack", 0),
            getattr(p, "weapon_durability", 0),
            getattr(p, "life", 30),
            getattr(p, "fatigue_damage", 0),
        )
        if before["players"].get(pid) != cur:
            return True
        zcur = (
            _zone_size(state, f"hand_{pid}"),
            _zone_size(state, f"library_{pid}"),
            _zone_size(state, f"graveyard_{pid}"),
        )
        if before["zones"].get(pid) != zcur:
            return True
    return False


def _emit_events(game: Game, events: list[Event]) -> None:
    for e in events:
        try:
            game.pipeline.emit(e)
        except Exception:
            # Some events crash without a fully set-up battlefield (e.g.
            # OBJECT_DESTROYED on a stub id). Swallow — the test only
            # cares about whether the effect_fn produced events at all.
            pass


def _fire_battlecry(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Build a scene, drop the minion in HAND, then ZONE_CHANGE to BATTLEFIELD."""
    game, p1, p2 = _new_scene()
    _populate_libraries(game, p1, p2)
    _populate_hands(game, p1, p2)

    # Populate boards so buff / damage / target-choice cards have legal targets.
    _populate_friendly_board(game, p1)
    _populate_enemy_board(game, p2)

    obj = game.create_object(
        name=card.name,
        owner_id=p1.id,
        zone=ZoneType.HAND,
        characteristics=card.characteristics,
        card_def=card,
    )

    before = _snapshot_state(game.state)

    # Fire battlecry directly. Mirrors the engine's own dispatch path which
    # calls `card_def.battlecry(obj, state)` after moving zone to BF.
    obj.zone = ZoneType.BATTLEFIELD
    # Move object id to battlefield zone too so subsequent state queries
    # (some battlecries iterate state.zones['battlefield'].objects) work.
    hand = game.state.zones.get(f"hand_{p1.id}")
    if hand and obj.id in hand.objects:
        hand.objects.remove(obj.id)
    bf = game.state.zones.get("battlefield")
    if bf and obj.id not in bf.objects:
        bf.objects.append(obj.id)

    events = card.battlecry(obj, game.state) or []
    return events, before, game, obj


def _fire_deathrattle(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Place on battlefield, then fire deathrattle directly."""
    game, p1, p2 = _new_scene()
    _populate_libraries(game, p1, p2)
    _populate_enemy_board(game, p2)

    obj = _place_minion(game, card, p1, ZoneType.BATTLEFIELD)
    before = _snapshot_state(game.state)
    events = card.deathrattle(obj, game.state) or []
    return events, before, game, obj


def _fire_spell(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Create the spell in HAND and call spell_effect with multiple target shapes.

    Hearthstone spells target wildly different things — some need a friendly
    minion (Hand of Protection, Bestial Wrath), some need an undamaged enemy
    (Backstab), some target the hero (Fireball at face). We try several
    target shapes in priority order and accept the first one that emits
    events. If all return [], we hand the empty result through to the
    verdict layer (which will mark it ENGINE GAP — exactly what we want).
    """
    game, p1, p2 = _new_scene()
    _populate_libraries(game, p1, p2)
    _populate_hands(game, p1, p2)
    friendlies = _populate_friendly_board(game, p1)
    enemies = _populate_enemy_board(game, p2)

    obj = game.create_object(
        name=card.name,
        owner_id=p1.id,
        zone=ZoneType.HAND,
        characteristics=card.characteristics,
        card_def=card,
    )
    obj.controller = p1.id

    # Build a priority-ordered list of candidate target slots. spell_effect
    # is called once per candidate until one returns non-empty events OR a
    # state mutation occurs. Includes the "no target" shape for buffs that
    # auto-pick their own target (Mark of the Wild, Power of the Wild, etc.).
    candidates: list[list] = []
    if enemies:
        # Find an undamaged enemy first (for Backstab and similar).
        undamaged = next((e for e in enemies if e.state.damage == 0), None)
        if undamaged:
            candidates.append([undamaged.id])
        # Then a damaged enemy (for Execute / Shadow Word: Pain).
        damaged = next((e for e in enemies if e.state.damage > 0), None)
        if damaged:
            candidates.append([damaged.id])
        # Then a high-attack enemy (for Big Game Hunter / Hunter's Mark).
        high_atk = max(enemies, key=lambda m: m.characteristics.power or 0)
        candidates.append([high_atk.id])
    if friendlies:
        # A friendly Beast (for Bestial Wrath / Houndmaster).
        beast = next(
            (f for f in friendlies
             if 'Beast' in (f.characteristics.subtypes or set())),
            None,
        )
        if beast:
            candidates.append([beast.id])
        # First friendly minion in general (for Mark of the Wild, Inner Fire).
        candidates.append([friendlies[0].id])
    if p2.hero_id:
        candidates.append([p2.hero_id])
    candidates.append([])  # no-target / auto-pick

    before = _snapshot_state(game.state)
    last_events: list[Event] = []
    for tgt in candidates:
        snap = _snapshot_state(game.state)
        try:
            events = card.spell_effect(obj, game.state, tgt) or []
        except TypeError:
            # Some legacy spell_effects took nested [[id]] target shape.
            try:
                events = card.spell_effect(obj, game.state, [tgt]) or []
            except Exception:
                events = []
        except Exception:
            events = []
        last_events = events
        # Accept the first shape that produced any signal.
        if events or _state_mutated(snap, game.state):
            return events, before, game, obj
        if game.state.pending_choice is not None:
            return events, before, game, obj

    return last_events, before, game, obj


def _fire_passive(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Drop the card on battlefield via create_object. setup_interceptors runs
    in `_handle_zone_change`-equivalent code paths inside create_object()."""
    game, p1, p2 = _new_scene()
    _populate_libraries(game, p1, p2)
    _populate_friendly_board(game, p1)
    _populate_enemy_board(game, p2)

    before = _snapshot_state(game.state)
    obj = _place_minion(game, card, p1, ZoneType.BATTLEFIELD)
    # No events to return — passive registration is the effect.
    return [], before, game, obj


def _fire_hero(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Heroes have no fire-on-play action; verify the card_def loads cleanly
    and starting_life is honoured by setup_hearthstone_player."""
    game = Game(mode="hearthstone")
    p1 = game.add_player("P1", life=30)
    game.setup_hearthstone_player(p1, card, HERO_POWERS["Mage"])  # any hero power
    hero = game.state.objects.get(p1.hero_id)
    before = {"interceptor_count": 0, "pending_choice": False, "players": {}}
    return [], before, game, hero


def _fire_hero_power(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Synthesize a HERO_POWER_ACTIVATE event and let the interceptor fire.

    Damages p1 and adds a damaged friendly minion so heals find a target.
    """
    game, p1, p2 = _new_scene()
    _populate_libraries(game, p1, p2)
    _populate_friendly_board(game, p1)
    _populate_enemy_board(game, p2)
    # Wound p1 so Lesser Heal / Life Tap / Reno-style heal triggers have
    # somewhere to land.
    p1.life = 20
    # Wound the friendly Yeti as a backup heal target for Lesser Heal's
    # "if hero is at max, heal minion" path.
    bf = game.state.zones.get("battlefield")
    if bf:
        for mid in bf.objects:
            m = game.state.objects.get(mid)
            if m and m.controller == p1.id and CardType.MINION in m.characteristics.types:
                m.state.damage = 1
                break

    # Replace p1's hero power with the one we're testing.
    hp_obj = game.create_object(
        name=card.name,
        owner_id=p1.id,
        zone=ZoneType.COMMAND,
        characteristics=card.characteristics,
        card_def=card,
    )
    p1.hero_power_id = hp_obj.id
    before = _snapshot_state(game.state)

    # Synthesise the activation event and let the registered interceptor
    # REACT with the effect.
    events: list[Event] = []
    try:
        evt = Event(
            type=EventType.HERO_POWER_ACTIVATE,
            payload={"hero_power_id": hp_obj.id, "controller": p1.id},
            source=hp_obj.id,
        )
        game.pipeline.emit(evt)
    except Exception:
        pass

    return events, before, game, hp_obj


def _fire_weapon(card: Any) -> tuple[list[Event], dict, Game, Any]:
    """Equip a weapon via ZONE_CHANGE to battlefield. make_weapon's setup
    registers a one-shot equip interceptor on ETB."""
    game, p1, p2 = _new_scene()
    _populate_libraries(game, p1, p2)
    before = _snapshot_state(game.state)
    obj = _place_minion(game, card, p1, ZoneType.BATTLEFIELD)
    return [], before, game, obj


# =============================================================================
# Verdict
# =============================================================================


def _gather_emitted_events(game: Game, returned_events: list[Event]) -> list[Event]:
    """Combine effect-fn return value with what the pipeline emitted afterwards."""
    log = list(getattr(game.state, "event_log", []) or [])
    return list(returned_events) + log


def _events_satisfy(
    text_expected: set[EventType], emitted: list[Event]
) -> tuple[bool, str]:
    """Did any of the expected events show up in the emit list?"""
    if not text_expected:
        return True, "no specific event expected from rules text"
    seen_types = {e.type for e in emitted if isinstance(e, Event)}
    overlap = text_expected & seen_types
    if overlap:
        return True, f"matched {[t.name for t in overlap]}"
    return False, f"expected one of {[t.name for t in text_expected]}; saw {[t.name for t in seen_types]}"


def _verdict(
    card: Any,
    classification: str,
    returned_events: list[Event],
    before: dict,
    game: Game,
) -> tuple[bool, str]:
    """
    True if the card 'did the thing' — at least one of:
      1. Expected EventType present in emitted events.
      2. A new interceptor was registered.
      3. A PendingChoice was stashed.
      4. Tracked state slots mutated.
    """
    emitted = _gather_emitted_events(game, returned_events)
    expected = _expected_event_types(getattr(card, "text", "") or "")

    # --- 1) event-type satisfaction
    ok_event, why = _events_satisfy(expected, emitted)
    if ok_event and expected:
        return True, f"emitted expected event ({why})"

    # --- 2) interceptor registered
    if len(game.state.interceptors) > before["interceptor_count"]:
        return True, "registered interceptor (passive / aura / hook)"

    # --- 3) PendingChoice stashed
    if game.state.pending_choice is not None:
        return True, "stashed PendingChoice (target-choice path)"

    # --- 4) state mutation (mana, armor, life, weapon)
    if _state_mutated(before, game.state):
        return True, "mutated player state (mana / armor / weapon / life)"

    # --- 5) the card's rules text doesn't require an EventType in our heuristic
    if not expected:
        # E.g. "Spell Damage +1" — we already would have caught this via
        # interceptor registration above. If we got here, the card text
        # genuinely doesn't promise an effect.
        if classification == "vanilla_minion" or _is_vanilla(card):
            return True, "vanilla — no effect to verify"
        if returned_events:
            return True, f"emitted {[e.type.name for e in returned_events if hasattr(e, 'type')]}"
        return True, "no specific assertion (text-free / mechanic-only)"

    # --- 6) hard fail: rules text claims X but nothing happened
    return False, (
        f"ENGINE GAP: rules text expects {[t.name for t in expected]} "
        f"but trigger fired with no observable effect. "
        f"Returned events: {[e.type.name for e in returned_events if hasattr(e, 'type')]}. "
        f"Emitted: {[e.type.name for e in emitted if hasattr(e, 'type')]}. "
        f"Interceptors before/after: {before['interceptor_count']}/{len(game.state.interceptors)}."
    )


# =============================================================================
# Test driver
# =============================================================================


def _safe_name(card: Any) -> str:
    return getattr(card, "name", "<unnamed>") or "<unnamed>"


_TEST_PARAMS: list[tuple[Any, str, str]] = []  # (card, classification, file_label)
for card in ALL_UNIQUE_CARDS:
    name = _safe_name(card)
    label = _FIRST_SEEN_LABEL.get(id(card), "unknown")
    if name in SKIPPED_CARDS:
        continue
    classification = _classify(card)
    if classification.startswith("skip:"):
        continue
    if _is_vanilla(card):
        # Vanilla minions don't need a real test — they would always pass.
        # But we still keep them in the suite as a smoke test, so the file
        # surfaces "this card was checked".
        classification = "vanilla_minion"
    _TEST_PARAMS.append((card, classification, label))


def _param_id(p: tuple[Any, str, str]) -> str:
    card, klass, label = p
    safe = re.sub(r"[^A-Za-z0-9]+", "_", _safe_name(card)).strip("_") or "card"
    return f"{label}-{klass}-{safe}"


@pytest.mark.parametrize("param", _TEST_PARAMS, ids=_param_id)
def test_card_interceptor(param) -> None:
    card, classification, _label = param
    name = _safe_name(card)
    if classification == "vanilla_minion":
        # Smoke check: the card is a valid CardDefinition and its
        # characteristics resolve to a Minion.
        assert card.name == name
        assert CardType.MINION in card.characteristics.types or \
               CardType.WEAPON in card.characteristics.types
        return

    if classification == "battlecry":
        events, before, game, _obj = _fire_battlecry(card)
    elif classification == "deathrattle":
        events, before, game, _obj = _fire_deathrattle(card)
    elif classification == "spell":
        events, before, game, _obj = _fire_spell(card)
    elif classification == "passive":
        events, before, game, _obj = _fire_passive(card)
    elif classification == "hero":
        events, before, game, _obj = _fire_hero(card)
        assert _obj is not None, f"{name}: hero object did not materialize"
        return
    elif classification == "hero_power":
        events, before, game, _obj = _fire_hero_power(card)
    elif classification == "weapon":
        events, before, game, _obj = _fire_weapon(card)
    else:
        pytest.skip(f"{name}: unhandled classification '{classification}'")
        return

    ok, why = _verdict(card, classification, events, before, game)
    assert ok, f"{name}: {why}"


# =============================================================================
# Summary main — emulates the spec's stdout format
# =============================================================================


def _runtest(p: tuple[Any, str, str]) -> tuple[str, str, str]:
    """Return (status, name, detail). status ∈ {'pass','fail','error'}."""
    card, classification, label = p
    name = _safe_name(card)
    try:
        if classification == "vanilla_minion":
            return ("pass", f"{label}::{name}", "vanilla")
        if classification == "battlecry":
            events, before, game, _ = _fire_battlecry(card)
        elif classification == "deathrattle":
            events, before, game, _ = _fire_deathrattle(card)
        elif classification == "spell":
            events, before, game, _ = _fire_spell(card)
        elif classification == "passive":
            events, before, game, _ = _fire_passive(card)
        elif classification == "hero":
            events, before, game, _ = _fire_hero(card)
            return ("pass", f"{label}::{name}", "hero loaded")
        elif classification == "hero_power":
            events, before, game, _ = _fire_hero_power(card)
        elif classification == "weapon":
            events, before, game, _ = _fire_weapon(card)
        else:
            return ("pass", f"{label}::{name}", f"skipped: {classification}")
        ok, why = _verdict(card, classification, events, before, game)
        if ok:
            return ("pass", f"{label}::{name}", why)
        return ("fail", f"{label}::{name}", why)
    except Exception as e:
        return ("error", f"{label}::{name}", f"{type(e).__name__}: {e}")


if __name__ == "__main__":
    passed: list[tuple[str, str]] = []
    failed: list[tuple[str, str]] = []
    errors: list[tuple[str, str]] = []

    for param in _TEST_PARAMS:
        status, name, detail = _runtest(param)
        if status == "pass":
            passed.append((name, detail))
        elif status == "fail":
            failed.append((name, detail))
        else:
            errors.append((name, detail))

    total = len(_TEST_PARAMS)
    skipped = len(SKIPPED_CARDS)

    print()
    print("=" * 70)
    print("=== Interceptor verification: Hearthstone CORE ===")
    print("=" * 70)
    # Per-file count summary
    per_file: dict[str, int] = {}
    for label, cards in ALL_CARDS_BY_FILE:
        per_file[label] = len(cards)
    print("\nCards in scope by file:")
    for label, count in per_file.items():
        print(f"  {label:12s}: {count}")
    print(f"\nUnique cards (dedupe): {len(ALL_UNIQUE_CARDS)}")
    print(f"Tests generated     : {total}")
    print(f"Skipped (manual list): {skipped}")
    print(f"  passed: {len(passed)}")
    print(f"  failed: {len(failed)}")
    print(f"  errors: {len(errors)}")
    if total:
        fail_rate = 100.0 * (len(failed) + len(errors)) / total
        print(f"  fail rate: {fail_rate:.1f}%")

    if failed:
        print("\n--- FAILURES (showing up to 25) ---")
        for name, msg in failed[:25]:
            print(f"  {name}: {msg}")

    if errors:
        print("\n--- ERRORS (showing up to 25) ---")
        for name, msg in errors[:25]:
            print(f"  {name}: {msg}")

    # ENGINE GAP categorization
    gap_counter: dict[str, list[str]] = {}
    for name, msg in failed:
        if "ENGINE GAP" in msg:
            # Pull out the "expects [X, Y]" segment as the category.
            m = re.search(r"expects \[([^\]]+)\]", msg)
            cat = m.group(1) if m else "uncategorized"
            gap_counter.setdefault(cat, []).append(name)
    if gap_counter:
        print("\n--- ENGINE GAP categories ---")
        ordered = sorted(gap_counter.items(), key=lambda kv: -len(kv[1]))
        for cat, names in ordered[:10]:
            print(f"  [{len(names):3d}] expected={cat}")
            for n in names[:3]:
                print(f"        - {n}")
            if len(names) > 3:
                print(f"        … +{len(names) - 3} more")

    sys.exit(0 if not failed and not errors else 1)
